use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-arithmetic-leaves-corrected";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");let changes=read(r.join("insertions.json"));let mut pins=BTreeMap::new();let mut changed=Vec::new();for(rel,h)in manifest["source_files_sha256"].as_object().unwrap(){let production=Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel);assert_eq!(hash(production),h.as_str().unwrap());let p=r.join("candidate").join(rel);if hash(&p)!=h.as_str().unwrap(){changed.push(rel.clone());let mut s=fs::read_to_string(&p).unwrap();let short=rel.strip_prefix("crates/zopro-core/src/").unwrap();for change in changes.as_array().unwrap().iter().rev().filter(|c|c["file"]==short){if let Some(expr)=change["new_expr"].as_str(){assert!(s.contains(expr));s=s.replacen(expr,change["old_expr"].as_str().unwrap(),1);}else{let text=change["inserted"].as_str().unwrap();assert!(s.contains(text));s=s.replacen(text,"",1);}}assert_eq!(s,fs::read_to_string(Path::new("/home/ubuntu/src/zk-tools/zopro").join(rel)).unwrap(),"recovery {rel}");}pins.insert(p.display().to_string(),hash(p));}assert_eq!(changed.len(),6);for rel in ["candidate/crates/zopro-core/src/arithmetic_trace.rs","driver.rs","support/perf.rs","patch.rs","setup.rs","design.md","insertions.json"]{let p=r.join(rel);pins.insert(p.display().to_string(),hash(p));}save(r.join("source-pins.json"),&json!(pins));save(r.join("source-audit.json"),&json!({"original_sources":170,"unchanged_originals":164,"changed":changed,"all_original_bytes_recovered":true,"new_module":"arithmetic_trace.rs","arithmetic_or_scheduler_changes":false,"explicit_cross_task_parent_IDs":true,"serial_thread_CPU_only":true,"diagnostic_cfg_only":true,"production_changed":false}));
 let text=serde_json::to_string(&read("/tmp/zopro-poseidon-direct-dot/native-plan.json")).unwrap().replace("/tmp/zopro-poseidon-direct-dot",R).replace("--cfg zopro_g2_prefix_records","--cfg zopro_g2_prefix_records --cfg zopro_arithmetic_trace");let mut plan:Value=serde_json::from_str(&text).unwrap();for step in plan["steps"].as_array_mut().unwrap(){if step["name"]=="core"{step["required_tests"]=json!(["arithmetic_trace::tests::explicit_parent_cpu_disabled_and_unwind","arithmetic_trace::tests::bounded_capacity_preserves_execution_and_reports_drops"]);}if step["name"]=="direct"{step["name"]=json!("trace");step["driver"]=json!(r.join("driver.rs"));step["additional_sources"]=json!([r.join("support/perf.rs")]);}}save(r.join("native-plan.json"),&plan);println!("Pinned6cfg-only originals/newboundedmodule;111coreexpected; originalallbytes recovered");}
